import sys
import jax.numpy as jnp
sys.path.append('storage/episteme')
# Using my sanitized V1 SOTA model which does NOT have dropout.
from episteme_sota_v1 import FactorizedMLP_with_RC_LN

def compute_loss(predictions, targets, params, x):
    mae = jnp.mean(jnp.abs(predictions - targets))
    curv = predictions[:, 2:, :] - 2.0 * predictions[:, 1:-1, :] + predictions[:, :-2, :]
    curv_pen = jnp.mean(curv * curv)
    return mae + 1e-4 * curv_pen

def _define_hyperparameters():
    # Using my original SOTA's hyperparameters.
    return {
        'learning_rate': 0.001,
        'rank_k': 320,
        'proj_rank': 320 # Using the original, large projection rank.
    }

def create_network(hparams):
    return FactorizedMLP_with_RC_LN(
        rank_k=hparams['rank_k'],
        proj_rank=hparams['proj_rank']
    )
